# Find nSamples, nPatches where allocation size is just above 524272
# and the number of items needed to overflow is small
best = []
for ns in range(0x7ffe, 1000, -1):
    for np in range(0x7ffe, 1000, -1):
        alloc = ((ns+1)*(np+1)*8) & 0xFFFFFFFF
        if alloc > 524272:
            items_needed = alloc // 8 + 1
            if items_needed < 100000:
                best.append((alloc, ns, np, items_needed))
                if len(best) > 10:
                    break
    if len(best) > 10:
        break
for b in best:
    print(b)
